    @{ id="razorpay2023"; src="https://web.archive.org/web/20250207075402/https://razorpay.com/blog/day-of-rds-multi-az-failover/"; sym="rds hardware failure mysql config data loss"; key="multi az failover financial system data loss"; pa="an rds hardware failure exposed an incorrect mysql configuration"; pb="the mysql configuration problem led to major data loss during the rds failover"; pc="a financial system lost data when the multi az failover exposed the bad config"; pd="the failover did not protect data because the mysql configuration was wrong"; se="RDS 硬件故障暴露 MySQL 配置错误，多可用区切换时数据丢失"; sf="RDS 硬件坏了切多可用区，结果 MySQL 配置不对，金融系统丢了很多数据"; rc="RDS 硬件故障暴露错误 MySQL 配置，多可用区切换期间发生重大数据丢失"; fix="修复 MySQL 配置和 RDS 故障切换，恢复数据" },
    @{ id="rust2023dns"; src="https://blog.rust-lang.org/inside-rust/2023/02/08/dns-outage-portmortem.html"; sym="static crates io dns record failed resolve deployment"; key="certificate and dns recreated during downtime"; pa="a deployment to crates dot io production infrastructure recreated certificates and dns records"; pb="the static crates dot io dns record failed to resolve for ten to fifteen minutes"; pc="both certificates and dns records were recreated during the deployment downtime"; pd="the deployment left the static crates dns record unresolvable for about fifteen minutes"; se="crates.io 部署时重建 DNS 记录导致 static.crates.io 解析失败"; sf="crates.io 上线时把证书和 DNS 记录一起重建，static.crates.io 十几分钟解析不出来"; rc="部署 crates.io 生产基础设施时，static.crates.io 的证书和 DNS 记录在停机期间重建，解析失败约 10-15 分钟"; fix="修复 DNS 记录和部署流程，增加解析检查" },
    @{ id="rust2023download"; src="https://blog.rust-lang.org/inside-rust/2023/07/21/crates-io-postmortem.html"; sym="crates io download url generation bug"; key="all crate downloads broken deployment"; pa="a deployment contained a bug in the download url generation"; pb="every crate download from crates dot io was broken for thirteen minutes"; pc="the bad url generation caused about three point seven million failed requests"; pd="cargo retries contributed to millions of failed download requests"; se="crates.io 下载 URL 生成 bug 导致所有 crate 下载失败"; sf="部署把下载 URL 生成逻辑改坏了，crates.io 所有 crate 下载都失败，cargo 重试把失败请求推到几百万"; rc="部署包含下载 URL 生成 bug，所有 crates.io crate 下载中断约 13 分钟，约 370 万请求失败"; fix="修复下载 URL 生成并回滚故障版本" },
    @{ id="stackoverflow2014"; src="https://web.archive.org/web/20201020103424/https://stackstatus.net/post/96025967369/outage-post-mortem-august-25th-2014"; sym="bad firewall config blocked stackoverflow"; key="stackexchange stackoverflow outage firewall"; pa="a bad firewall configuration blocked stackexchange and stackoverflow"; pb="the firewall misconfiguration took stack overflow offline"; pc="the site became reachable again after the firewall config was corrected"; pd="fixing the firewall rule restored stack overflow access"; se="错误防火墙配置导致 Stack Overflow 无法访问"; sf="防火墙规则配错了，Stack Overflow 整个站打不开"; rc="错误防火墙配置阻断 StackExchange 与 Stack Overflow"; fix="回滚防火墙配置，恢复访问" },
    @{ id="travis2016images"; src="https://web.archive.org/web/20221220114914/https://blog.travis-ci.com/2016-09-30-the-day-we-deleted-our-vm-images/"; sym="automated cleanup deleted base vm images gce"; key="age based image cleanup removed stable images"; pa="an automated age based cleanup job deleted stable base vm images"; pb="the google compute engine image cleanup removed images that builds still needed"; pc="builds failed because the base images had been deleted by the cleanup job"; pd="the cleanup job age rule deleted stable images and broke builds"; se="自动按年龄清理 GCE VM 镜像误删稳定基础镜像"; sf="自动清理按年龄把稳定的基础镜像删了，构建全失败"; rc="自动按年龄清理 Google Compute Engine VM 镜像的任务误删稳定基础镜像"; fix="恢复镜像，修复清理任务的年龄与保护条件" },
    @{ id="turso2023"; src="https://blog.turso.tech/incident-2023-12-04-data-leak-and-loss-in-some-free-tier-databases-7cba5bc7"; sym="turso backup identifiers misconfigured data leak loss"; key="free tier database backup access data loss"; pa="incorrectly configured database backup identifiers led to data leaks for free tier customers"; pb="the subsequent fix resulted in possible data loss for affected free tier databases"; pc="backup identifiers exposed some free tier database data"; pd="fixing the backup identifiers may have caused data loss in some free tier databases"; se="Turso 备份标识配置错误导致免费层数据库泄漏并可能丢失数据"; sf="备份 ID 配错了，免费层数据库数据泄漏；修的时候又可能把数据弄丢"; rc="数据库备份标识配置错误导致免费层客户数据泄漏，后续修复又可能导致部分数据丢失"; fix="修正备份标识与访问控制，评估并恢复受影响数据" }
)

if ($incidents.Count -ne 30) { throw "expected 30 incidents, got $($incidents.Count)" }

$rows = New-Object System.Collections.ArrayList
$n = 0
function Store-Case([string]$q, [string]$evalQuery, [string]$layer, [string]$rc, [string]$fix, [string]$src) {
    $script:n++
    $log = Join-Path $env:TEMP ("scx-holdout-{0:D3}-{1}.log" -f $script:n, [guid]::NewGuid().ToString("N"))
    $text = ("{0}`n公开复盘, 来源: {1}`n根因: {2}" -f $q, $src, $rc)
    Write-Utf8 $log $text
    $prev = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try { $out = (& $Binary --query $q --store 1 --fix $fix --mem-dir $MemDir $log 2>&1 | Out-String) }
    finally { $ErrorActionPreference = $prev }
    if ($out -notmatch "stored case=([^\s]+) added=yes") { throw "store failed case $($script:n): $q`n$out" }
    $id = $Matches[1]
    $h = $id.Split('_')[-1]
    $note = "target=$h source=$src"
    [void]$rows.Add([pscustomobject]@{ query = $evalQuery; layer = $layer; case_id = $id; note = $note })
}

foreach ($c in $incidents) {
    Store-Case $c.sym $c.sym "literal" $c.rc $c.fix $c.src
    Store-Case $c.key $c.key "literal" $c.rc $c.fix $c.src
    Store-Case $c.pa  $c.pb  "paraphrase" $c.rc $c.fix $c.src
    Store-Case $c.pc  $c.pd  "paraphrase" $c.rc $c.fix $c.src
    Store-Case $c.se  $c.sf  "semantic" $c.rc $c.fix $c.src
}

$lines = @("query,layer,case_id,note")
foreach ($r in $rows) {
    $lines += ((@($r.query, $r.layer, $r.case_id, $r.note) | ForEach-Object { CsvField ([string]$_) }) -join ",")
}
Write-Utf8 $Csv ($lines -join "`n")

$l = @($rows | Where-Object { $_.layer -eq "literal" }).Count
$p = @($rows | Where-Object { $_.layer -eq "paraphrase" }).Count
$s = @($rows | Where-Object { $_.layer -eq "semantic" }).Count
Write-Host ("holdout corpus: total={0} literal={1} paraphrase={2} semantic={3}" -f $rows.Count, $l, $p, $s)
Write-Host "next: powershell -File scripts\holdout-build.ps1 -Csv eval-real\holdout-cases.csv -Out eval-real\holdout-baseline.json"
